416:             } else {
417:                 (elapsed * 1000.0).round() as i64
418:             };
419:             (ts, elapsed)
420:         };
421: 
422:         // Monotonicity clamping
423:         let elapsed_s = if raw_elapsed <= self.last_elapsed_s {
