55:         payload_ids::SMART_BATTERY => DatBatteryRecord::parse(payload).map(DatRecordPayload::Battery),
56:         _ => Ok(DatRecordPayload::Unknown {
57:             payload_id,
58:             raw: payload,
59:         }),
60:     }
