15: /// Decoded Smart Battery Diagnostics from on-board `.DAT` blackbox recordings.
16: #[derive(Clone, Copy, Debug, PartialEq)]
17: pub struct DatBatteryRecord {
18:     /// Total pack voltage in millivolts.
19:     pub total_voltage_mv: u32,
20:     /// Instantaneous battery current draw in milliamperes (negative indicates discharge).
21:     pub current_ma: i32,
22:     /// Battery pack temperature in degrees Celsius.
23:     pub temperature_c: f32,
24:     /// State of charge percentage (0% to 100%).
25:     pub soc_percent: u8,
26:     /// Individual cell voltages in millivolts for cells 1 through 12.
27:     pub cell_voltages_mv: [u16; 12],
28:     /// Individual cell internal resistances in milliohms ($m\Omega$) for cells 1 through 12.
29:     pub cell_resistances_mohm: [u16; 12],
30: }
31: 
32: impl DatBatteryRecord {
33:     /// Parses a `.DAT` Payload ID 0x0A byte slice into a [`DatBatteryRecord`].
34:     pub fn parse(payload: &[u8]) -> Result<Self> {
35:         if payload.len() < MIN_DAT_BATTERY_PAYLOAD_LEN {
36:             return Err(FlightReaderError::PayloadTooShort {
37:                 minimum: MIN_DAT_BATTERY_PAYLOAD_LEN,
38:                 available: payload.len(),
39:             });
40:         }
41: 
42:         let total_voltage_mv = LittleEndian::read_u32(&payload[0..4]);
43:         let current_ma = LittleEndian::read_i32(&payload[4..8]);
44:         let temp_raw = LittleEndian::read_i16(&payload[8..10]);
45:         let temperature_c = f32::from(temp_raw) / 10.0;
46:         let soc_percent = payload[10];
47: 
48:         let mut cell_voltages_mv = [0u16; 12];
49:         let mut cell_resistances_mohm = [0u16; 12];
50: 
51:         // Decode cell voltages (offset 11..35, 2 bytes per cell, up to 12 cells)
52:         let available_cells = if payload.len() >= 11 {
53:             ((payload.len() - 11) / 2).min(12)
54:         } else {
55:             0
56:         };
57: 
58:         for (i, cell_mv) in cell_voltages_mv.iter_mut().enumerate().take(available_cells) {
59:             let offset = 11 + i * 2;
60:             *cell_mv = LittleEndian::read_u16(&payload[offset..offset + 2]);
61:         }
62: 
63:         // Decode cell internal resistances (offset 35..59, 2 bytes per cell, up to 12 cells)
64:         if payload.len() >= 35 {
65:             let available_res = ((payload.len() - 35) / 2).min(12);
66:             for (i, cell_res) in cell_resistances_mohm.iter_mut().enumerate().take(available_res) {
67:                 let offset = 35 + i * 2;
68:                 *cell_res = LittleEndian::read_u16(&payload[offset..offset + 2]);
69:             }
70:         }
71: 
72:         Ok(Self {
73:             total_voltage_mv,
74:             current_ma,
75:             temperature_c,
76:             soc_percent,
77:             cell_voltages_mv,
78:             cell_resistances_mohm,
79:         })
80:     }
81: 
