83:     #[inline]
84:     #[must_use]
85:     pub fn total_voltage_v(&self) -> f32 {
86:         self.total_voltage_mv as f32 / 1000.0
87:     }
88: 
89:     /// Instantaneous current draw in amperes.
90:     #[inline]
91:     #[must_use]
92:     pub fn current_a(&self) -> f32 {
93:         self.current_ma as f32 / 1000.0
94:     }
95: 
96:     /// Returns the cell voltage in volts for cell index `0..12`.
97:     #[must_use]
98:     pub fn cell_voltage_v(&self, cell_idx: usize) -> Option<f32> {
99:         if cell_idx < 12 && self.cell_voltages_mv[cell_idx] > 0 {
100:             Some(f32::from(self.cell_voltages_mv[cell_idx]) / 1000.0)
101:         } else {
102:             None
103:         }
104:     }
105: 
106:     /// Returns the number of active cells with non-zero voltage.
107:     #[must_use]
108:     pub fn active_cell_count(&self) -> usize {
109:         self.cell_voltages_mv
110:             .iter()
111:             .filter(|&&mv| mv > 0)
112:             .count()
113:     }
114: 
115:     /// Returns the average cell voltage in volts across all active cells.
116:     #[must_use]
117:     pub fn average_cell_voltage_v(&self) -> f32 {
118:         let count = self.active_cell_count();
119:         if count == 0 {
120:             0.0
121:         } else {
122:             let sum_mv: u32 = self
123:                 .cell_voltages_mv
124:                 .iter()
125:                 .filter(|&&mv| mv > 0)
126:                 .map(|&mv| u32::from(mv))
127:                 .sum();
128:             (sum_mv as f32 / count as f32) / 1000.0
129:         }
130:     }
131: 
132:     /// Returns the maximum voltage delta between cells in millivolts.
133:     #[must_use]
134:     pub fn cell_voltage_delta_mv(&self) -> u16 {
135:         let active_cells: Vec<u16> = self
136:             .cell_voltages_mv
137:             .iter()
138:             .copied()
139:             .filter(|&mv| mv > 0)
140:             .collect();
141: 
142:         if active_cells.len() < 2 {
143:             0
144:         } else {
145:             let min_v = active_cells.iter().min().copied().unwrap_or(0);
146:             let max_v = active_cells.iter().max().copied().unwrap_or(0);
147:             max_v.saturating_sub(min_v)
148:         }
149:     }
150: }
